mapper.select:
/* CoachingMapper.selectStrengthTexts */
SELECT factor        AS factor
     , observation   AS observation
     , `line`        AS `line`
     , question      AS question
FROM coaching_strength
WHERE use_yn = 'Y'
  AND school_level = #{schoolLevel}
  AND lpa_class = #{lpaClass}
  AND factor IN
  #{f}
